#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by scripts/ring_mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enP2p1s0f0np0 | grep -q clsact || tc qdisc add dev enP2p1s0f0np0 clsact
tc qdisc show dev enP2p1s0f1np1 | grep -q clsact || tc qdisc add dev enP2p1s0f1np1 clsact
tc filter show dev enP2p1s0f0np0 ingress pref 49159 | grep -q flower || tc filter add dev enP2p1s0f0np0 ingress protocol 0x88b5 pref 49159 handle 49159 flower skip_sw src_mac 4c:bb:47:7e:0c:e3 dst_mac 4c:bb:47:7d:4e:05 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:00:42:b2 pipe action mirred egress redirect dev enP2p1s0f1np1
tc -s filter show dev enP2p1s0f0np0 ingress pref 49159 | grep -q in_hw || { echo 'rule pref 49159 on enP2p1s0f0np0 is not in hardware'; exit 3; }
tc filter show dev enP2p1s0f1np1 ingress pref 49165 | grep -q flower || tc filter add dev enP2p1s0f1np1 ingress protocol 0x88b5 pref 49165 handle 49165 flower skip_sw src_mac 4c:bb:47:00:42:b2 dst_mac 4c:bb:47:7d:4e:06 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:7e:0c:e3 pipe action mirred egress redirect dev enP2p1s0f0np0
tc -s filter show dev enP2p1s0f1np1 ingress pref 49165 | grep -q in_hw || { echo 'rule pref 49165 on enP2p1s0f1np1 is not in hardware'; exit 3; }
ip route show exact 10.250.1.3/32 | grep -q . || ip route add 10.250.1.3/32 via 10.250.0.2 dev enp1s0f0np0 src 10.250.0.1
ip route show exact 10.250.6.3/32 | grep -q . || ip route add 10.250.6.3/32 via 10.250.7.4 dev enP2p1s0f1np1 src 10.250.7.1
for d in roceP2p1s0f1 rocep1s0f0; do systemctl start dsv41-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f1 rocep1s0f0; do systemctl is-active --quiet dsv41-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
